js='''const S=DATA;const tl=gsap.timeline({paused:true});window.__timelines={main:tl};
tl.from('#banner',{y:-920,duration:1,ease:'power3.inOut'},2.05);tl.from('#banner',{opacity:0,duration:.4,ease:'power2.out'},.15);
S.forEach((s,i)=>{const[a,b,k]=s,q='#s'+i;
if(i){tl.set(q,{opacity:1},a);tl.from(q,{x:1080,duration:.4,ease:'expo.inOut'},a);tl.set('#s'+(i-1),{opacity:0},a+.42)}
const entries=[{y:65,opacity:0,ease:'power3.out'},{x:-60,opacity:0,ease:'expo.out'},{scale:.88,rotation:-3,opacity:0,ease:'back.out(1.05)'}];document.querySelectorAll(q+' .enter').forEach((el,j)=>tl.from(el,{...entries[j%3],duration:.55},a+.15+j*.095));
if(document.querySelector(q+' .orbit')){tl.from(q+' .orbit',{scale:.85,opacity:0,duration:.65,ease:'sine.out'},a+.2);tl.to(q+' .orbit',{rotation:35,duration:b-a-.5,ease:'sine.inOut'},a+.4)}
tl.to(q+' .hero',{y:-15,scale:1.025,duration:Math.max(.3,b-a-1),ease:'sine.inOut'},a+.9);
if(document.querySelector(q+' .left'))tl.to(q+' .left',{y:-15,rotation:-5,duration:Math.max(.3,b-a-1.1),ease:'sine.inOut'},a+1);
if(document.querySelector(q+' .right'))tl.to(q+' .right',{y:12,rotation:5,duration:Math.max(.3,b-a-1.1),ease:'sine.inOut'},a+1);
});'''.replace('DATA',json.dumps(S,ensure_ascii=False))
